      ex: { prompt: 'Write isMatch(s, p) returning true if the whole string s matches pattern p, where "." matches any single character and "*" matches zero or more of the preceding element.', py: "from functools import lru_cache\n\ndef isMatch(s, p):\n    @lru_cache(maxsize=None)\n    def match(i, j):\n        if j == len(p):\n            return i == len(s)\n        first = i < len(s) and p[j] in (s[i], '.')\n        if j + 1 < len(p) and p[j + 1] == '*':\n            return match(i, j + 2) or (first and match(i + 1, j))\n        return first and match(i + 1, j + 1)\n    return match(0, 0)\n", sig: "(string s, string p) -> bool", java: "class Solution {\n    private Boolean[][] memo;\n    public boolean isMatch(String s, String p) {\n        memo = new Boolean[s.length() + 1][p.length() + 1];\n        return match(s, p, 0, 0);\n    }\n    private boolean match(String s, String p, int i, int j) {\n        if (memo[i][j] != null) return memo[i][j];\n        boolean ans;\n        if (j == p.length()) ans = i == s.length();\n        else {\n            boolean first = i < s.length() && (p.charAt(j) == s.charAt(i) || p.charAt(j) == '.');\n            if (j + 1 < p.length() && p.charAt(j + 1) == '*') ans = match(s, p, i, j + 2) || (first && match(s, p, i + 1, j));\n            else ans = first && match(s, p, i + 1, j + 1);\n        }\n        return memo[i][j] = ans;\n    }\n}\n", cpp: "class Solution {\npublic:\n    bool isMatch(string s, string p) {\n        memo.assign(s.size() + 1, vector<int>(p.size() + 1, -1));\n        return match(s, p, 0, 0);\n    }\nprivate:\n    vector<vector<int>> memo;\n    bool match(const string& s, const string& p, size_t i, size_t j) {\n        if (memo[i][j] >= 0) return memo[i][j];\n        bool ans;\n        if (j == p.size()) ans = i == s.size();\n        else {\n            bool first = i < s.size() && (p[j] == s[i] || p[j] == '.');\n            if (j + 1 < p.size() && p[j + 1] == '*') ans = match(s, p, i, j + 2) || (first && match(s, p, i + 1, j));\n            else ans = first && match(s, p, i + 1, j + 1);\n        }\n        return memo[i][j] = ans;\n    }\n};\n", fn: 'isMatch', params: 's, p', cases: [{ args: ['aa', 'a'], expect: false }, { args: ['aa', 'a*'], expect: true }, { args: ['ab', '.*'], expect: true }, { args: ['mississippi', 'mis*is*p*.'], expect: false }, { args: ['aab', 'c*a*b'], expect: true }], solution: "function isMatch(s,p){const m=new Map();const d=(i,j)=>{const k=i*(p.length+1)+j;if(m.has(k))return m.get(k);let a;if(j===p.length)a=i===s.length;else{const f=i<s.length&&(p[j]===s[i]||p[j]==='.');a=p[j+1]==='*'?d(i,j+2)||(f&&d(i+1,j)):f&&d(i+1,j+1)}m.set(k,a);return a};return d(0,0)}", hint: 'On "x*", either skip it or consume one matching character and stay.' },
